window.ScripturaLexicons.BDAG_PART_0131 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exousiazo-bdag\" data-source=\"BDAG\" data-search=\"ἐξουσιάζω exousiázō verbo ter direito ou poder sobre algo ou alguém BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξουσιάζω</td><td>verbo</td><td>ter direito ou poder sobre algo ou alguém</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exousiastikos-bdag\" data-source=\"BDAG\" data-search=\"ἐξουσιαστικός, ή, όν exousiastikós adjetivo autoritativo; dotado de autoridade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξουσιαστικός, ή, όν</td><td>adjetivo</td><td>autoritativo; dotado de autoridade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exoche-bdag\" data-source=\"BDAG\" data-search=\"ἐξοχή, ῆς, ἡ exochḗ substantivo feminino destaque; proeminência BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξοχή, ῆς, ἡ</td><td>substantivo feminino</td><td>destaque; proeminência</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exochos-bdag\" data-source=\"BDAG\" data-search=\"ἔξοχος, ον éxochos adjetivo proeminente; eminente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔξοχος, ον</td><td>adjetivo</td><td>proeminente; eminente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exypnizo-bdag\" data-source=\"BDAG\" data-search=\"ἐξυπνίζω exypnízō verbo despertar; acordar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξυπνίζω</td><td>verbo</td><td>despertar; acordar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exypnos-bdag\" data-source=\"BDAG\" data-search=\"ἔξυπνος, ον éxypnos adjetivo acordado; desperto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔξυπνος, ον</td><td>adjetivo</td><td>acordado; desperto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exo-bdag\" data-source=\"BDAG\" data-search=\"ἔξω éxō advérbio de lugar; preposição com genitivo; substantivado fora; para fora; exterior; os de fora BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔξω</td><td>advérbio de lugar; preposição com genitivo; substantivado</td><td>fora; para fora; exterior; os de fora</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exothen-bdag\" data-source=\"BDAG\" data-search=\"ἔξωθεν éxōthen advérbio de lugar; preposição com genitivo de fora; exterior; os de fora BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔξωθεν</td><td>advérbio de lugar; preposição com genitivo</td><td>de fora; exterior; os de fora</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exotheo-bdag\" data-source=\"BDAG\" data-search=\"ἐξωθέω exōthéō verbo expulsar; conduzir à praia; encalhar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξωθέω</td><td>verbo</td><td>expulsar; conduzir à praia; encalhar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exoteros-bdag\" data-source=\"BDAG\" data-search=\"ἐξώτερος, α, ον exṓteros adjetivo comparativo; uso superlativo exterior; mais afastado; extremo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξώτερος, α, ον</td><td>adjetivo comparativo; uso superlativo</td><td>exterior; mais afastado; extremo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eoika-bdag\" data-source=\"BDAG\" data-search=\"ἔοικα éoika verbo; perfeito antigo assemelhar-se; ser semelhante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔοικα</td><td>verbo; perfeito antigo</td><td>assemelhar-se; ser semelhante</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heortazo-bdag\" data-source=\"BDAG\" data-search=\"ἑορτάζω heortázō verbo celebrar uma festa; festejar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑορτάζω</td><td>verbo</td><td>celebrar uma festa; festejar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heorte-bdag\" data-source=\"BDAG\" data-search=\"ἑορτή, ῆς, ἡ heortḗ substantivo feminino festa; festividade; celebração BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑορτή, ῆς, ἡ</td><td>substantivo feminino</td><td>festa; festividade; celebração</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epangelia-bdag\" data-source=\"BDAG\" data-search=\"ἐπαγγελία, ας, ἡ epangelía substantivo feminino promessa; compromisso; oferta; garantia de concordância BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπαγγελία, ας, ἡ</td><td>substantivo feminino</td><td>promessa; compromisso; oferta; garantia de concordância</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epangellomai-bdag\" data-source=\"BDAG\" data-search=\"ἐπαγγέλλομαι epangéllomai verbo médio depoente prometer; oferecer; professar; pretender ser competente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπαγγέλλομαι</td><td>verbo médio depoente</td><td>prometer; oferecer; professar; pretender ser competente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epangelma-bdag\" data-source=\"BDAG\" data-search=\"ἐπάγγελμα, ατος, τό epángelma substantivo neutro promessa; coisa prometida BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπάγγελμα, ατος, τό</td><td>substantivo neutro</td><td>promessa; coisa prometida</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epago-bdag\" data-source=\"BDAG\" data-search=\"ἐπάγω epágō verbo ocasionar; trazer algo sobre alguém BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπάγω</td><td>verbo</td><td>ocasionar; trazer algo sobre alguém</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epagonizomai-bdag\" data-source=\"BDAG\" data-search=\"ἐπαγωνίζομαι epagōnízomai verbo médio depoente lutar; contender; empenhar-se intensamente em defesa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπαγωνίζομαι</td><td>verbo médio depoente</td><td>lutar; contender; empenhar-se intensamente em defesa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epathroizo-bdag\" data-source=\"BDAG\" data-search=\"ἐπαθροίζω epathroízō verbo reunir mais; aumentar em número BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπαθροίζω</td><td>verbo</td><td>reunir mais; aumentar em número</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epainetos-bdag\" data-source=\"BDAG\" data-search=\"Ἐπαίνετος, ου, ὁ Epaínetos nome próprio masculino Epêneto; cristão da Ásia mencionado em Romanos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἐπαίνετος, ου, ὁ</td><td>nome próprio masculino</td><td>Epêneto; cristão da Ásia mencionado em Romanos</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article id=\"entry-exousiazo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξουσιάζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exousiázō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξουσιάζω</span> (ver verbete anterior). Primeiro futuro <span class=\"greek\">ἐξουσιάσω</span>, LXX; TestSol 1:5; primeiro aoristo, terceira pessoa do singular <span class=\"greek\">ἐξουσίασεν</span>, Ec 5:18; futuro passivo <span class=\"greek\">ἐξουσιασθήσομαι</span> (Aristot., Eth. Eud. 1, 5, p. 1216a, 2; Dionys. Hal. 9, 44, 6; inscrições, apenas papiros tardios, LXX; TestSol 1:5): «ter o direito de controlar, ter direito ou poder sobre alguma coisa ou alguém». <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐξουσιάζων</span>, «aquele que exerce autoridade» (Ec 10:4, 5; TestSol C 9:8), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:25</a>. Especialmente, o direito ou poder de fazer com algo aquilo que se julga conveniente (IG XIV, 79, 4), com o genitivo daquilo sobre o qual se exerce poder (CIG III, 4584, 4, <span class=\"greek\">θυγατέρα</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐξουσιάζειν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μνήματος</span>). Do marido e da esposa com referência aos deveres conjugais: <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἰδίου</span> <span class=\"greek\">σώματος</span>, «ter poder sobre o próprio corpo [dela ou dele]», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 7:4</a>. Paulo emprega a voz passiva num jogo de palavras com <span class=\"greek\">ἔξεστιν</span>: <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐξουσιασθήσομαι</span> <span class=\"greek\">ὑπό</span> <span class=\"greek\">τινος</span>, «não me deixarei dominar ou sujeitar à autoridade de coisa alguma», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 6:12</a>. — M-M. TW.</p></section></article>\n<article id=\"entry-exousiastikos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξουσιαστικός, ή, όν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exousiastikós⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξουσιαστικός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (Ec 8:4 Sym; Vett. Val. 6, 3; Iamblichus; comparativo -<span class=\"greek\">ώτερον</span> em Polyb. 5, 26, 3): «relativo a estar livre da aprovação externa, dotado de autoridade, autoritativo», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1:27</a>, variante de leitura (cf. doctrina inpotentabilis na versão latina antiga, códice e).</p></section></article>\n<article id=\"entry-exoche-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξοχή, ῆς, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exochḗ⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξοχή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (de <span class=\"greek\">ἐξέχω</span>, «sobressair, projetar-se»). Da ideia de «algo que se projeta de uma superfície» (por exemplo, Diod S 5, 30, figuras em relevo nos escudos; Theod., Job 39:28; Sym., SSol 2:14 e Jr 13:4; Jos., Ant. 3, 135; 231), chega-se facilmente à ideia de posição especial: «destaque, proeminência» (cf. o sentido «excelência, vantagem» em Cicero, Ad Att. 4, 15, 7; Vett. Val. 17, 23; e <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐξοχήν</span>, «por excelência», em Strabo 1, 2, 10; Philo, Leg. All. 1, 106; SIG 810, 16 [55 d.C.]; OGI 764, 52 [séc. II a.C.]). <span class=\"greek\">ἄνδρες</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">πόλεως</span>, «os homens mais proeminentes da cidade», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.23\" target=\"_blank\" rel=\"noopener noreferrer\">At 25:23</a>. — DELG, s.v. 1 <span class=\"greek\">ἔχω</span> 4. M-M.</p></section></article>\n<article id=\"entry-exochos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔξοχος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦éxochos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἔξοχος</span>, <span class=\"greek\">ον</span> (ver verbete anterior; Hom. e outros na poesia; na prosa, Cornutus 16, p. 20, 21; Plut., Lucian, Herodian e outros autores tardios, incluindo Vett. Val. 16, 1): «proeminente, eminente» (SibOr 5, 284). <span class=\"greek\">μάρτυς</span>, «confessor proeminente até a morte», isto é, «mártir distinto», MPol 19:1. Superlativo (Ps.-Lucian, Asin. 2; OGI 640, 16; POxy 1469, 1): <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐξοχώτατον</span>, «aquilo que é mais excelente», 1Cl 33:4. — M-M.</p></section></article>\n<article id=\"entry-exypnizo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξυπνίζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exypnízō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξυπνίζω</span>; futuro <span class=\"greek\">ἐξυπνίσω</span>. Passivo: futuro, terceira pessoa do singular <span class=\"greek\">ἐξυπνισθήσεται</span> (SyrBar 12:4); terceira pessoa do plural <span class=\"greek\">ἐξυπνισθήσονται</span>, Jó 14:12; primeiro aoristo, terceira pessoa do singular <span class=\"greek\">ἐξυπνίσθη</span>, LXX (ver <span class=\"greek\">ὕπνος</span>; Plut., Mor. 979d; 1044d; M. Ant. 6, 31; Jz 16:14 B, 20 B; 3Km 3:15; pseudepígrafos; substituto helenístico de <span class=\"greek\">ἀφυπνίζω</span>: Phryn., pp. 96 e 224 Lob.): «despertar, acordar alguém»; <span class=\"greek\">τινά</span>, «alguém», a respeito de pessoas adormecidas (Chrysipp., Stoic. II 334, 25); <span class=\"greek\">τὸν</span> <span class=\"greek\">κεντυρίωνα</span>, «o centurião», GPt 10:38. Num jogo de palavras com <span class=\"greek\">κοιμάω</span> (sobre ambos os vocábulos usados a respeito da morte, ver Jó 14:12; em nossa passagem, porém, esse jogo ressalta a ideia de que, para Jesus, ressuscitar alguém é tão fácil quanto despertá-lo do sono. Sobre a morte como «sono», ver RLattimore, Themes in Greek and Latin Epitaphs, 1962, 164s; cf. Il. 16, 672, «o sono e a morte, irmãos gêmeos»; Soph., Ajax 832; Electra 509), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11:11</a>. — M-M. TW.</p></section></article>\n<article id=\"entry-exypnos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔξυπνος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦éxypnos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἔξυπνος</span>, <span class=\"greek\">ον</span> (ver verbete anterior; PGiss 19, 4; LXX, En): «acordado, desperto»; <span class=\"greek\">ἔ</span>. <span class=\"greek\">γίνεσθαι</span>, «despertar» (Syntipas, p. 58, 5; 117, 2; 1Esdr 3:3; En 13:9; Jos., Ant. 11, 34); <span class=\"greek\">ἔ</span>. <span class=\"greek\">γενόμενος</span>, «tendo despertado» (Leontius 8, p. 15, 14; TestLevi 5:7), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.27\" target=\"_blank\" rel=\"noopener noreferrer\">At 16:27</a>. — DELG, s.v. <span class=\"greek\">ὕπνος</span>. M-M. TW.</p></section></article>\n<article id=\"entry-exo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔξω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦éxō⟧</span><span class=\"separator\">·</span><span>advérbio de lugar; preposição com genitivo; substantivado</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἔξω</span>, advérbio de lugar (ver <span class=\"greek\">ἔξωθεν</span>; Hom. e autores posteriores).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">①</span> Relativo à posição além de uma delimitação ou fronteira: «fora, do lado de fora».</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> Em função adverbial.</p>\n<p class=\"entry-text\"><span class=\"greek\">α</span>. Com verbo que não designa movimento: <span class=\"greek\">δεδεμένον</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">θύραν</span> <span class=\"greek\">ἔ</span>., «amarrado à porta, do lado de fora», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 11:4</a>. <span class=\"greek\">ἔ</span>. <span class=\"greek\">εἶναι</span> (X., An. 2, 6, 3; 7, 2, 29), <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἐρήμοις</span> <span class=\"greek\">τόποις</span> <span class=\"greek\">ἦν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1:45</a>; <span class=\"greek\">ἑστάναι</span> <span class=\"greek\">ἔ</span>., «estar de pé do lado de fora» (Gn 24:31; Dt 24:11; Sir 21:23), Mt 12:46s; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3:31</a> (cf. v. 32); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:20</a>; 13:25; GEb 121, 33. Com <span class=\"greek\">πρός</span> e dativo: <span class=\"greek\">πρὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θύρᾳ</span> <span class=\"greek\">ἔ</span>., <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.16\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 18:16</a>; <span class=\"greek\">πρὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">μνημείῳ</span> <span class=\"greek\">ἔ</span>., <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.11\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 20:11</a>; <span class=\"greek\">καθῆσθαι</span> <span class=\"greek\">ἔ</span>., «estar sentado do lado de fora», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.69\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:69</a>; <span class=\"greek\">προσεύχεσθαι</span> <span class=\"greek\">ἔ</span>., «orar do lado de fora», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:10</a>; <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἔχειν</span> <span class=\"greek\">τι</span>, «ter algo com os ombros descobertos», Hs 9, 2, 4; 9, 9, 5; 9, 13, 8. O verbo deve ser suprido em passagens como <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 22:15</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">β</span>. Como substituto de adjetivo: «exterior, de fora» (Pla., Phdr. 248a, <span class=\"greek\">ὁ</span> <span class=\"greek\">ἔξω</span> <span class=\"greek\">τόπος</span>; a mesma expressão em BGU 1114, 5 [4 a.C.]; cf. POxy 903, 20, <span class=\"greek\">τὰς</span> <span class=\"greek\">ἔξω</span> <span class=\"greek\">θύρας</span>). <span class=\"greek\">αἱ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">πόλεις</span>, «as cidades estrangeiras» (literalmente «de fora», isto é, não judaicas), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.11\" target=\"_blank\" rel=\"noopener noreferrer\">At 26:11</a>; Hv 2, 4, 3. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">ἄνθρωπος</span>, «nosso ser exterior» (isto é, o corpo, como em Zosimus 13: Hermet. IV, p. 107, 16), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 4:16</a> (ver <span class=\"greek\">ἄνθρωπος</span> 5a); diferentemente, <span class=\"greek\">οἱ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἄνθρωποι</span>, 2Cl 13:1 (ver ③ abaixo). <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔ</span>. (oposto a <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔσω</span>), «o lado exterior» (Thu. 7, 69, 4), 2Cl 12:2; cf. v. 4 (dito apócrifo de Jesus).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> Em função de preposição com genitivo, respondendo à pergunta «onde?»: «fora de, do lado de fora» (Thu. 8, 67, 2 e outros; Nm 35:5, 27; Jdth 10:18; 13:3; TestJob 28:8, <span class=\"greek\">ἔ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">πόλεως</span>; Jos., Ant. 13, 91; 101; Tat. 2, 1, <span class=\"greek\">ἀλαζονείας</span> <span class=\"greek\">ἔ</span>.), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:33</a>. <span class=\"greek\">ἔ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">παρεμβολῆς</span>, «fora do arraial», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:11</a>; 1Cl 4:11 (cf. Êx 29:14 e outros); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.16\" target=\"_blank\" rel=\"noopener noreferrer\">At 28:16</a>, variante de leitura. <span class=\"greek\">ἔ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">πύλης</span>, «fora da porta [da cidade]», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:12</a> (Jos., Bell. 4, 360, <span class=\"greek\">ἔ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">πυλῶν</span>); <span class=\"greek\">ἔ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">θύρας</span>, «fora da porta», Hv 3, 9, 6; <span class=\"greek\">ἔ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">οἰκίας</span>, «fora da casa», 1Cl 12:6 (cf. Js 2:19).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">②</span> Relativo à posição fora de uma área ou de seus limites como resultado de uma ação: «para fora» (Hom. e outros).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> <span class=\"greek\">ἐξέρχεσθαι</span> <span class=\"greek\">ἔ</span>., «sair [para fora]» (Js 2:19; cf. Sl 40:7), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.75\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:75</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.62\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:62</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.4\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 19:4</a>, 5; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 3:12</a>. <span class=\"greek\">ἐξῆλθεν</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">προαύλιον</span>, «saiu para fora, ao pátio», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.68\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:68</a>. <span class=\"greek\">ἐξῆλθεν</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">πρὸς</span> <span class=\"greek\">αὐτούς</span> (cf. Gn 24:29; Jz 19:25), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.29\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 18:29</a>. <span class=\"greek\">ἔ</span>. <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τινα</span>, «mandar alguém para fora», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.34\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:34</a>; <span class=\"greek\">ἄγειν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.4\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 19:4</a>, 13; <span class=\"greek\">ἐξάγειν</span> (Gn 15:5; Jz 19:25), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8:23</a>, variante; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.50\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24:50</a>; <span class=\"greek\">προάγειν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.30\" target=\"_blank\" rel=\"noopener noreferrer\">At 16:30</a>; <span class=\"greek\">βάλλειν</span> (M. Ant. 12, 25, <span class=\"greek\">βάλε</span> <span class=\"greek\">ἔξω</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:13</a>; 13:48; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14:35</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.31\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 12:31</a>, variante; 15:6; 1Jo 4:18; <span class=\"greek\">ἐκβάλλειν</span> (2Cr 29:16), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:28</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.37\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6:37</a>; 9:34s; 12:31; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.40\" target=\"_blank\" rel=\"noopener noreferrer\">At 9:40</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 11:2</a>, variante. <span class=\"greek\">δεῦρο</span> <span class=\"greek\">ἔ</span>., «vem para fora!», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.43\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11:43</a> (ver <span class=\"greek\">δεῦρο</span> 1).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> Em função de preposição com genitivo, respondendo à pergunta «para onde?»: «para fora [de dentro], para fora de» (Hom. e outros). <span class=\"greek\">ἀπελθεῖν</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">συνεδρίου</span>, «sair do Sinédrio», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">At 4:15</a>. Igualmente após <span class=\"greek\">ἐξέρχεσθαι</span> (Polyaenus 3, 7, 3; cf. Jos., Ant. 8, 399), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:14</a>; 21:17; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 16:13</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:13</a> (<span class=\"greek\">ἐξέρχ</span>. <span class=\"greek\">ἔ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">παρεμβολῆς</span>, como em Nm 31:13); <span class=\"greek\">ἐκπορεύεσθαι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 11:19</a>; <span class=\"greek\">ἀποστέλλειν</span> <span class=\"greek\">τινά</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5:10</a>; <span class=\"greek\">ἐκφέρειν</span> <span class=\"greek\">τινά</span> (Lv 4:12), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8:23</a>; <span class=\"greek\">βάλλειν</span> <span class=\"greek\">τινά</span>, 2Cl 7:4; <span class=\"greek\">ἐκβάλλειν</span> <span class=\"greek\">τινά</span> (Lv 14:40), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:39</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12:8</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:29</a>; 20:15; com acusativo subentendido, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.58\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:58</a>; <span class=\"greek\">ἀπορρίπτειν</span> <span class=\"greek\">τινά</span>, Hv 3, 5, 5; <span class=\"greek\">σύρειν</span> <span class=\"greek\">τινά</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 14:19</a>; <span class=\"greek\">ἕλκειν</span> <span class=\"greek\">τινά</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.30\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:30</a>; <span class=\"greek\">προπέμπειν</span> <span class=\"greek\">τινά</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.5\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:5</a> (sobre <span class=\"greek\">ἕως</span> <span class=\"greek\">ἔ</span>., cf. 1Km 9:26).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">③</span> Relativo à exclusão de um grupo: «de fora», substantivado com artigo: «pessoa de fora, estranho». <span class=\"greek\">οἱ</span> <span class=\"greek\">ἔξω</span>, «os que estão de fora» (2Macc 1:16; Petosiris, Fgm. 6, linha 206 = «os estrangeiros»; figuradamente, Thu. 5, 14, 3), daqueles que não pertenciam ao círculo dos discípulos, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4:11</a>. Dos não cristãos em geral (Iambl., Vi. Pyth. 35, 252, dos não pitagóricos; Simplicius em Epict., p. 132, 6, daqueles que não são ascetas), 1Co 5:12s; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 4:5</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 4:12</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἄνθρωποι</span>, «os homens de fora» (como em Lucian, De Merc. Cond. 21), 2Cl 13:1. — DELG, s.v. <span class=\"greek\">ἐξ</span>. M-M. TW.</p></section></article>\n<article id=\"entry-exothen-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔξωθεν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦éxōthen⟧</span><span class=\"separator\">·</span><span>advérbio de lugar; preposição com genitivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἔξωθεν</span>, advérbio de lugar (ver verbete anterior; Aeschyl., Hdt. e autores posteriores).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">①</span> Relativo à procedência de uma fonte exterior: «de fora, vindo de fora».</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> Usado como advérbio (Hierocles 7, p. 430, <span class=\"greek\">ἡ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">βία</span> = «força que vem de fora»; Jz 12:9; Jdth 13:1; Ath., R. 53, 8, <span class=\"greek\">τῆς</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἀνάγκης</span>): <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">εἰσπορευόμενον</span>, «aquilo que entra [numa pessoa] vindo de fora», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 7:18</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> Em função de preposição com genitivo (autores trágicos, X. e outros): «de fora». <span class=\"greek\">ἔ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">ἀνθρώπου</span> <span class=\"greek\">εἰσπορευόμενον</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">αὐτόν</span>, «aquilo que entra no ser humano vindo de fora dele», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 7:15</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">②</span> Relativo a uma posição além de determinada área: «fora».</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> (Dio Chrys. 17 [34], 21; 67 [17], 1; PFlor 50, 99; Êx 26:35 e outros; Jos., Bell. 5, 201; Vi. 118, <span class=\"greek\">ἔ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">κώμης</span>; TestZeb 3:6). <span class=\"greek\">ἔ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">πόλεως</span>, «fora da cidade» (Aeneas Tact. 951; TestJob 24:1), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 14:20</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">αὐλὴ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ναοῦ</span>, «o pátio exterior do templo», Ap 11:2a. <span class=\"greek\">οὐθὲν</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἐστιν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀληθείας</span>, «nada está fora da verdade», Hv 3, 4, 3.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> Em contraste com <span class=\"greek\">ἔσωθεν</span> (Aeneas Tact. 1331; Diocles 141, p. 178, 13; Gn 6:14; Êx 25:11 e outros; PGM 5, 307; Just., A I, 16, 13; D. 35, 3 [cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:15</a>]; Tat. 22, 1; Ath. 25, 3), Mt 23:27s; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 7:5</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 5:1</a>, variante de leitura (Plut., Dio 972 [31, 2], <span class=\"greek\">μία</span> [sc. <span class=\"greek\">ἐπιστολή</span>] <span class=\"greek\">δ</span>’ <span class=\"greek\">ἦν</span> <span class=\"greek\">ἐπιγεγραμμένη</span>); IRo 3:2; Agr 25b.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">③</span> Relativo à posição na superfície, ao lado de fora, àquilo que é exterior; como substituto de adjetivo (Demosth. 18, 9, <span class=\"greek\">οἱ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">λόγοι</span>; 4Macc 6:34; 18:2; Jos., Ant. 14, 477): <span class=\"greek\">ὁ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">κόσμος</span>, «adorno exterior», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3:3</a>; <span class=\"greek\">ἡ</span> <span class=\"greek\">ἔ</span>. <span class=\"greek\">ἐπιφάνεια</span>, «a superfície exterior dos olhos de Judas», obscurecida por suas feições inchadas, Papias (3:2). — Como substantivo com artigo, <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔξωθεν</span>, «o exterior» (SIG 813a, 6; Ez 41:17), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:25</a>; Lc 11:39s.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">④</span> Relativo à posição fora de uma área ou de seus limites como resultado de uma ação: «para fora, fora». <span class=\"greek\">ἔκβαλε</span> <span class=\"greek\">ἔ</span>., «lança para fora» = «deixa de fora» (ver <span class=\"greek\">ἐκβάλλω</span> 4), Ap 11:2b.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">⑤</span> Relativo à exclusão de um grupo: «de fora», substantivado com artigo, <span class=\"greek\">οἱ</span> <span class=\"greek\">ἔ</span>., «os de fora», isto é, os não cristãos, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 3:7</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4:11</a>, variante de leitura (cf. Hdt. 9, 5; Diod S 19, 70, 3; Himerius, Or. [Ecl.] 5, 18; Celsus 3, 14; Jos., Bell. 4, 179; Ant. 15, 316). — M-M.</p></section></article>\n<article id=\"entry-exotheo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξωθέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exōthéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξωθέω</span> (ver <span class=\"greek\">ὠθέω</span>); futuro <span class=\"greek\">ἐξώσω</span>, LXX; primeiro aoristo <span class=\"greek\">ἐξῶσα</span> (Tdf. apresenta a forma mais antiga <span class=\"greek\">ἐξέωσα</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.45\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:45</a>; assim também Polyaenus 8, 46, p. 408, 17; Sb 7205, 13; PSI 41, 16; PFlor 58, 9), terceira pessoa do singular <span class=\"greek\">ἐξέωσεν</span>, 4Km 17:21. Passivo: futuro, terceira pessoa do plural <span class=\"greek\">ἐξωσθήσονται</span>, LXX; aoristo, terceira pessoa do plural <span class=\"greek\">ἐξώσθησαν</span>; particípio perfeito <span class=\"greek\">ἐξωσμένος</span>, LXX, e <span class=\"greek\">ἐξεωσμένον</span>, 2Km 14:14, variante (Hom., Il. 14, 494, <span class=\"greek\">ἐκ</span> <span class=\"greek\">δ</span>’ <span class=\"greek\">ὦσε</span> <span class=\"greek\">γλήνην</span>; trágicos, Hdt. e outros; papiros, LXX; TestGad 5:2; Philo, Poster. Cai. 55; Jos., Bell. 5, 338; 342).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">①</span> Forçar alguém a deixar determinada área: «empurrar para fora, expulsar»; <span class=\"greek\">τινά</span>, «alguém», fazer alguém sair de um lugar à força (Thu., X., Polyb. e outros). <span class=\"greek\">ἐξῶσεν</span> (<span class=\"greek\">ἐξέωσεν</span>, texto recebido, Tdf.) <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">προσώπου</span> <span class=\"greek\">τινός</span>, «expulsou de diante de alguém», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.45\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:45</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">②</span> Na terminologia náutica: «impelir ou conduzir à praia, encalhar, aportar à praia» (assim Thu., X. e outros); <span class=\"greek\">τὸ</span> <span class=\"greek\">πλοῖον</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">αἰγιαλόν</span>, «[conduzir] o navio à praia», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.39\" target=\"_blank\" rel=\"noopener noreferrer\">At 27:39</a>. — M-M.</p></section></article>\n<article id=\"entry-exoteros-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξώτερος, α, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exṓteros⟧</span><span class=\"separator\">·</span><span>adjetivo comparativo; uso superlativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξώτερος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span> (Strabo; PFlor 100, 11 e 27; POxy 896, 14; PSI IV, 284, 2 [séc. VI d.C.]; LXX): comparativo adjetival do advérbio <span class=\"greek\">ἔξω</span> (B-D-F §62; Rob. 298).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">①</span> Relativo a uma área fora de determinada fronteira: «exterior, de fora» (em contraste com o interior ou o centro; cf. 3Km 6:29s). <span class=\"greek\">ἐξώτεροι</span> <span class=\"greek\">τεθήσονται</span>, «elas [as pedras] serão colocadas do lado de fora», Hs 9, 7, 5; cf. 9, 8, 3; 5; 7. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐξώτερα</span> <span class=\"greek\">μέρη</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οἰκοδομῆς</span>, «as partes externas do edifício», Hs 9, 9, 3.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">②</span> Empregado como superlativo: «mais afastado, extremo» (Êx 26:4). <span class=\"greek\">τὸ</span> <span class=\"greek\">σκότος</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐ</span>., «as trevas mais exteriores», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:12</a>; 22:13; 25:30 (ApcEsdr 4:37, p. 29, 16 Tdf.; Just., D. 76, 5, sobre <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:41</a>). — DELG, s.v. <span class=\"greek\">ὠθέω</span>. M-M.</p></section></article>\n<article id=\"entry-eoika-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔοικα</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦éoika⟧</span><span class=\"separator\">·</span><span>verbo; perfeito antigo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἔοικα</span> (Hom. e outros; no sentido de «parecer», também Jó 6:3, 25; Jos., C. Ap. 2, 175; Just., Tat.): antigo perfeito de <span class=\"greek\">εἴκω</span>, «ser como, assemelhar-se»; <span class=\"greek\">τινί</span>, «a alguém ou a alguma coisa» (Hes., Fgm. 263 Rz., <span class=\"greek\">ποταμῷ</span> <span class=\"greek\">ῥέοντι</span> <span class=\"greek\">ἐοικώς</span>), <span class=\"greek\">κλύδωνι</span> <span class=\"greek\">θαλάσσης</span>, «à onda do mar», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1:6</a>; <span class=\"greek\">ἀνδρί</span>, «a um homem», v. 23. — DELG. M-M.</p></section></article>\n<article id=\"entry-heortazo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑορτάζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦heortázō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἑορτάζω</span>; futuro <span class=\"greek\">ἑορτάσω</span>; primeiro aoristo, imperativo da segunda pessoa do plural <span class=\"greek\">ἑορτάσατε</span> e infinitivo <span class=\"greek\">ἑορτάσαι</span>, LXX (ver verbete seguinte; Eur., Hdt. e outros; Plut., Mor. 378b; Paus. 2, 11, 3; OGI 194, 28 [restaurado]; 493, 26; PSI 1242, 8 [séc. I a.C./I d.C.]; Mitt-Wilck. I/2, 490, 6 e 11 = BGU 646, 6; 11; LXX; Ath. 14, 1): «celebrar uma festividade, festejar», acerca da Páscoa (Jos., Ant. 5, 20), como figura da vida cristã, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 5:8</a> (Philo, Sacr. Abel. 111, <span class=\"greek\">ἑορτὴ</span> <span class=\"greek\">ψυχῆς</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀρεταῖς</span> … <span class=\"greek\">μόνος</span> <span class=\"greek\">ἑορτάζει</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">σοφός</span>). — DELG, s.v. <span class=\"greek\">ἑορτή</span>. M-M.</p></section></article>\n<article id=\"entry-heorte-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑορτή, ῆς, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦heortḗ⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἑορτή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (ver verbete anterior; Hom. e posteriores; inscrições, papiros, LXX; ParJer 7:31; EpArist, Philo, Joseph.; Ar. 10:8; Just., Mel.; Ath. 26, 3): «dia ou sucessão de dias marcados por celebração ou observância periódica; festa, festividade, celebração». <span class=\"greek\">ἐν</span> <span class=\"greek\">μέρει</span> <span class=\"greek\">ἑορτῆς</span>, «quanto a uma festa», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 2:16</a>. Mais especificamente, <span class=\"greek\">ἡ</span> <span class=\"greek\">ἑ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πάσχα</span>, «a festa da Páscoa» (Êx 34:25), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:41</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 13:1</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πάσχα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἑ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">Ἰουδαίων</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6:4</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἑ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀζύμων</span>, «a festa dos pães asmos», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:1</a>; cf. GPt 2:5 (Mel., P. 93, 695). <span class=\"greek\">ἡ</span> <span class=\"greek\">ἑ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">Ἰουδαίων</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">σκηνοπηγία</span>, «a festa judaica dos Tabernáculos ou Cabanas», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7:2</a>; <span class=\"greek\">ἡ</span> <span class=\"greek\">ἑ</span>., «a festa», designa, conforme o contexto, determinada festividade: a Páscoa, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:5</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:42</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.45\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:45</a>; 11:56; 12:12, 20 e outros; a festa dos Tabernáculos, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7:8</a>, 10s, 14, 37. — Em <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:1</a>, os testemunhos e as edições oscilam entre o indefinido <span class=\"greek\">ἑ</span>., «uma festa», e o definido <span class=\"greek\">ἡ</span> <span class=\"greek\">ἑ</span>., «a festa» (quanto à atestação e interpretação, ver Hdb. ad loc.; JUbbink, NThSt 5, 1922, 131–36). Apenas <span class=\"greek\">ἑ</span>., designando a festa dos Tabernáculos, PtK 2, p. 14, 29. — <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἑ</span>., «durante a festa» (Jos., Bell. 2, 89; Ant. 20, 109, <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑ</span>.), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:5</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:2</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.45\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:45</a>; 7:11; 12:20; <span class=\"greek\">εἶναι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἑορτῇ</span>, «participar da festa», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 2:23</a> (CBurchard, ZNW 61, 1970, 157–88 — também <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:2</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:5</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7:11</a>). <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἑορτήν</span>, «para a festa», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.29\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 13:29</a> (cf. BGU 596, 7 [84 d.C.], <span class=\"greek\">ὅπως</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἑορτὴν</span> <span class=\"greek\">περιστερείδια</span> <span class=\"greek\">ἡμεῖν</span> <span class=\"greek\">ἀγοράσῃ</span>). <span class=\"greek\">ἀναβαίνειν</span> (isto é, a Jerusalém) <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἑ</span>., <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7:8</a>, 10 (cf. BGU 48, 18, <span class=\"greek\">ἐὰν</span> <span class=\"greek\">ἀναβῇς</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἑορτῇ</span>); <span class=\"greek\">ἔρχεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἑ</span>. (Jos., Bell. 1, 73; 6, 300), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.45\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:45</a>; 11:56; 12:12. <span class=\"greek\">τ</span>. <span class=\"greek\">ἑορτῆς</span> <span class=\"greek\">μεσούσης</span>, «quando a festa estava pela metade», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7:14</a>. <span class=\"greek\">τ</span>. <span class=\"greek\">ἑορτῆς</span> <span class=\"greek\">παυσαμένης</span>, GPt 14:58. <span class=\"greek\">κατὰ</span> <span class=\"greek\">ἑορτήν</span>, «em cada festa [da Páscoa]», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:15</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15:6</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:17</a>, variante (deveria restringir-se à Páscoa? Qualquer festividade poderia oferecer ocasião apropriada para libertar um preso. Cf. Heliod. 8, 7, p. 227, 6ss Bekker: <span class=\"greek\">ἡ</span> <span class=\"greek\">δέσποινα</span> … <span class=\"greek\">τήμερον</span> <span class=\"greek\">ἀφήσειν</span> <span class=\"greek\">ἐπηγγείλατο</span> [Theagenes], <span class=\"greek\">ἑορτήν</span> <span class=\"greek\">τινα</span> <span class=\"greek\">πάτριον</span> <span class=\"greek\">εὐωχεῖν</span> <span class=\"greek\">μέλλουσα</span>, «a senhora prometeu libertar [Teágenes] hoje, pois pretende celebrar uma festa tradicional»). <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔθος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἑορτῆς</span>, «conforme o costume da festa», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:42</a>. <span class=\"greek\">τ</span>. <span class=\"greek\">ἑορτὴν</span> <span class=\"greek\">ποιεῖν</span>, «celebrar a festa» (Ael. Aristid. 29, 4 K. = 40, p. 752 D.; Vi. Aesopi G 123 P.; Êx 23:16), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.21\" target=\"_blank\" rel=\"noopener noreferrer\">At 18:21</a> D. De uma festividade alegre (em contraste com <span class=\"greek\">πένθος</span>, «tempo de tristeza»), Dg 4:5. — DELG. M-M.</p></section></article>\n<article id=\"entry-epangelia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαγγελία, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epangelía⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐπαγγελία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (ver <span class=\"greek\">ἀγγέλλω</span>; Demosth. e outros; Aristot., EN 10, 1, p. 1164a, 29; inscrições, papiros, LXX, pseudepígrafos, Philo, Joseph.). Em muitos autores, <span class=\"greek\">ἐ</span>. designa o ato de tornar alguma coisa publicamente conhecida; na literatura aqui considerada, porém, apresenta com maior frequência o significado de:</p>\n<p class=\"entry-text\"><span class=\"sense-number\">①</span> Declaração de que se fará alguma coisa, com a implicação de obrigação de cumprir o que se declarou: «promessa, compromisso, oferta» (Polyb. 1, 43, 6; 7, 13, 2; 18, 11, 1 e outros; Diod S 1, 5, 3; 4, 16, 2; Epict. 1, 4, 3, <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀρετὴ</span> <span class=\"greek\">ταύτην</span> <span class=\"greek\">ἔχει</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐπαγγελίαν</span> <span class=\"greek\">εὐδαιμονίαν</span> <span class=\"greek\">ποιῆσαι</span>; Michel 473, 10; IPriene 123, 9; 1Macc 10:15; Philo, Mut. Nom. 201; Jos., Ant. 5, 307).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> De seres humanos: <span class=\"greek\">ὅπως</span> <span class=\"greek\">ἀποδῶμεν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἣν</span> <span class=\"greek\">ἐπειγγειλάμεθα</span>, «para que cumpramos a promessa que fizemos», GJs 7:1. De alguém que afirma ser cristão, IEph 14:2.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> Na literatura considerada, mais geralmente, das promessas divinas (Herm. Wr., em Stob. I 387, 15 W.; Fgm. XXIII 8, variante de leitura; cf. Herm. Wr. 18, 14; Jos., Ant. 2, 219; Oração de Manassés [= Odes 12] 6; PsSol 12:6; talvez Sl 55:9).</p>\n<p class=\"entry-text\"><span class=\"greek\">α</span>. Promessa de Deus: no singular, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.39\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:39</a>; Rm 4:13s, 16; 9:9 (onde <span class=\"greek\">λόγος</span> deve ser suprido com o genitivo <span class=\"greek\">ἐπαγγελίας</span>: «esta palavra é uma palavra de promessa»); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 3:17</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 3:9</a>; 1Cl 26:1; 2Cl 15:4; B 5:7; 16:9. No plural, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 9:4</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 7:1</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 3:16</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:6</a>; 8:6; 11:17; 1Cl 27:1; H 3, 4; ApcPt Rainer (figura etimológica; cf. 1a e 1b<span class=\"greek\">β</span>). Expressões preposicionais: <span class=\"greek\">δι</span>’ <span class=\"greek\">ἐπαγγελίας</span>, «por meio de uma promessa ou em virtude de uma promessa», Gl 3:18b; 4:23; também <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἐπαγγελίας</span>, 3:18a. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐπαγγελίᾳ</span>, «com promessa», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 6:2</a>. <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐπαγγελίαν</span>, «segundo a promessa» (PSI 281, 58, <span class=\"greek\">κατὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἐπανγελίας</span> <span class=\"greek\">αὐτου</span>; semelhante em IK IX–X/2: Nikaia II/1, 702, 6; 1Esdr 1:7; Orig., C. Cels. 1, 68, 43), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.23\" target=\"_blank\" rel=\"noopener noreferrer\">At 13:23</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.29\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 3:29</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 1:1</a> (sobre essas três expressões, ver New Docs 4, 147). — O genitivo acompanha <span class=\"greek\">ἐ</span>. por diferentes razões: para designar aquele de quem procede a promessa, (<span class=\"greek\">τ</span>.) <span class=\"greek\">θεοῦ</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 4:20</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1:20</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 3:21</a>; 2Cl 11:1; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 1:1</a>, variante; para indicar o objeto prometido (Jos., Ant. 3, 77, <span class=\"greek\">τ</span>. <span class=\"greek\">ἀγαθῶν</span>): <span class=\"greek\">ἐ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">αἰωνίου</span> <span class=\"greek\">κληρονομίας</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:15</a>; <span class=\"greek\">τ</span>. <span class=\"greek\">ζωῆς</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 4:8</a>; <span class=\"greek\">τ</span>. <span class=\"greek\">παρουσίας</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 3:4</a>; para indicar aqueles aos quais a promessa se destina: <span class=\"greek\">τ</span>. <span class=\"greek\">πατέρων</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15:8</a> (TestJob 20:1; quanto a <span class=\"greek\">βεβαιῶσαι</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐ</span>., cf. InsPriene 123, 9, <span class=\"greek\">ἐβεβαίωσεν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἐπαγγελίαν</span>). — Por outro lado, <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐπαγγελίας</span> é frequentemente acrescentado, como uma espécie de genitivo de qualidade, para indicar a relação do substantivo com a promessa: <span class=\"greek\">γῆ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἐ</span>., «terra prometida», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:9</a> (TestAbr A 8, p. 85, 16 [Stone p. 18] e outros); <span class=\"greek\">τέκνα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἐ</span>., «filhos da promessa», isto é, nascidos em consequência da promessa, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 9:8</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.28\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 4:28</a>; <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἐ</span>., <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 1:13</a>; <span class=\"greek\">διαθῆκαι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἐ</span>., <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 2:12</a>. Como genitivo objetivo em <span class=\"greek\">πίστις</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐ</span>., «fé na promessa», B 6:17. — <span class=\"greek\">ἐ</span>. seguido de infinitivo: <span class=\"greek\">εἰσελθεῖν</span>, «entrar», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:1</a>. — <span class=\"greek\">ἐ</span>. <span class=\"greek\">γενομένη</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πατέρας</span>, «promessa feita aos pais», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.32\" target=\"_blank\" rel=\"noopener noreferrer\">At 13:32</a>; também <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πατ</span>., <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.6\" target=\"_blank\" rel=\"noopener noreferrer\">At 26:6</a> (Diod S 2, 60, 4, <span class=\"greek\">γεγενημένη</span> <span class=\"greek\">ἐ</span>. = «promessa feita»). — Da promessa de Cristo (Orig., C. Cels. 2, 2, 43), 2Cl 5:5.</p>\n<p class=\"entry-text\"><span class=\"greek\">β</span>. Com especificação daquilo que foi prometido (Vi. Aesopi G 79 P.; PsSol 12:6), 1Jo 2:25 (figura etimológica como em Hs 1, 7). Hv 3, 2, 1 (<span class=\"greek\">ἐπαγγελίαι</span> junto de <span class=\"greek\">δῶρα</span>). <span class=\"greek\">δεκτὸς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐ</span>., «destinatário do benefício prometido», ApcPt Rainer 20. Seguido de genitivo epexegético: <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πνεύματος</span>, «aquilo que foi prometido, a saber, o Espírito», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.33\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:33</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 3:14</a>. Seguido de genitivo daquele que faz a promessa: <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρός</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24:49</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:4</a>; <span class=\"greek\">κομίσασθαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐ</span>., «obter a promessa», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.36\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:36</a>; 11:13, variante, 39; <span class=\"greek\">λαβεῖν</span>, «receber», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:13</a>; 2Cl 11:7; <span class=\"greek\">ἀπολαβεῖν</span>, «receber», B 15:7; Hv 2, 2, 6; <span class=\"greek\">ἡ</span> <span class=\"greek\">μέλλουσα</span> <span class=\"greek\">ἐ</span>., «a promessa futura», 2Cl 10:3s.</p>\n<p class=\"entry-text\"><span class=\"greek\">γ</span>. Nem sempre é possível traçar uma distinção precisa entre <span class=\"greek\">α</span> e <span class=\"greek\">β</span> (cf. Hippol., Ref. 5, 7, 19, <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">λουτροῦ</span>): <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:17</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 3:22</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 3:6</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:12</a>, 15, 17; 11:9b, 33; 1Cl 10:2; 34:7. — FBaumgärtel, Verheissung: Zur Frage des evang. Verständnisses des AT, 1952.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">②</span> O emprego condensado de <span class=\"greek\">ἐ</span>. em <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.21\" target=\"_blank\" rel=\"noopener noreferrer\">At 23:21</a> é, de fato, uma extensão da acepção ① e envolve dois componentes fundamentais: acolhimento de um pedido e aprovação dele; «garantia de concordância». <span class=\"greek\">προσδέχεσθαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> <span class=\"greek\">ἐ</span>., «aguardar de alguém a garantia ou anuência» (isto é, que se faça o que foi proposto). — DELG, s.v. <span class=\"greek\">ἄγγελος</span>. M-M. EDNT. TW.</p></section></article>\n<article id=\"entry-epangellomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαγγέλλομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epangéllomai⟧</span><span class=\"separator\">·</span><span>verbo médio depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐπαγγέλλομαι</span> (ver verbete anterior; frequentemente «anunciar, proclamar»; a voz ativa atestada desde Hom.; a voz média, única encontrada na literatura aqui considerada, desde Soph., Hdt. e Thu.; inscrições, papiros, LXX; TestSol 3:7; 20:2 P; TestAbr A 3, p. 79, 31 [Stone p. 6]; ApcMos 41; EpArist; Philo, Joseph., Just., Tat.). Primeiro aoristo <span class=\"greek\">ἐπηγγειλάμην</span>; perfeito <span class=\"greek\">ἐπήγγελμαι</span>, este último também com significado passivo (cf. Kühner-G. I 120; ver ①ⓑ).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">①</span> Declarar que se fará alguma coisa, com a implicação de obrigação de cumprir o que foi declarado: «prometer, oferecer».</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> De promessas e ofertas humanas: <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span>, «prometer alguma coisa a alguém» (PTebt 58, 32 [séc. III a.C.]; 1Macc 11:28; 2Macc 4:8), <span class=\"greek\">ἐλευθερίαν</span> <span class=\"greek\">τινί</span>, «liberdade a alguém», Hs 5, 2, 7; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 2:19</a>; <span class=\"greek\">ἐπαγγελίαν</span>, GJs 7:1. — Da Sibila, <span class=\"greek\">ὸ̔</span> <span class=\"greek\">ἐπηγγείλατο</span> <span class=\"greek\">ὅραμα</span>, Hv 3, 2, 3. Com dativo e infinitivo subsequente (cf. Polyb. 1, 46, 4; PTebt 411, 9; 3Macc 1:4; Jos., C. Ap. 1, 57): <span class=\"greek\">ἐπηγγείλαντο</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">ἀργύριον</span> <span class=\"greek\">δοῦναι</span>, «prometeram dar-lhe dinheiro», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:11</a> (cf. 2Macc 4:27).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> De Deus: «prometer» (2Macc 2:18; 3Macc 2:10; PsSol); <span class=\"greek\">τὶ</span>, «alguma coisa», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 4:21</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 1:2</a>; ITr 11:2; <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span>, «algo a alguém» (Sb 7172, 27s [217 a.C.], <span class=\"greek\">ἃ</span> <span class=\"greek\">ἐπηγγείλαντο</span> [os deuses] <span class=\"greek\">αὐτῷ</span>), Hv 5:7; Dg 10:2. <span class=\"greek\">στέφανον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀγαπῶσιν</span>, «a coroa da vida aos que o amam», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1:12</a>; cf. 2:5 (<span class=\"greek\">ἧς</span> <span class=\"greek\">ἐπηγγείλατο</span>, com atração do relativo = <span class=\"greek\">ἣν</span> <span class=\"greek\">ἐ</span>.). <span class=\"greek\">τὸ</span> <span class=\"greek\">ποτήριον</span> <span class=\"greek\">ὸ̔</span> <span class=\"greek\">ἐπηγγειλάμην</span> <span class=\"greek\">σοι</span>, «o cálice que te prometi», ApcPt Rainer 11. <span class=\"greek\">γῆν</span> <span class=\"greek\">Χαναναίων</span>, «a terra dos cananeus», AcPl Ha 8, 14. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐπαγγελία</span>, <span class=\"greek\">ἣν</span> <span class=\"greek\">αὐτὸς</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἡμῖν</span>, «aquilo que ele mesmo nos prometeu», 1Jo 2:25 (<span class=\"greek\">ἡ</span> <span class=\"greek\">ἐπαγγελία</span>, <span class=\"greek\">ἣν</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τινι</span>, como em Esth 4:7; cf. também Diod S 15, 6, 5, <span class=\"greek\">ἐπηγγείλατο</span> <span class=\"greek\">ἐπαγγελίαν</span>); cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:17</a>, variante; Hv 1, 3, 4 (ver Joly ad loc., acerca da pontuação); Hs 1:7. Seguido de infinitivo (Jos., Ant. 3, 23; Just., A I, 40, 7), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:5</a>; 2Cl 11:6; Hv 3, 1, 2. Seguido de <span class=\"greek\">ὅτι</span>, 1Cl 32:2; de <span class=\"greek\">λέγων</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:26</a>. Uso absoluto (também PPetr I, 29, 12 [séc. III a.C.]): «fazer uma promessa»; <span class=\"greek\">τινί</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:13</a>. Deus é descrito como <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐπαγγειλάμενος</span>, «aquele que prometeu», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.23\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:23</a>; 11:11 (uma inscrição frígia [IGR IV, 766] denomina <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐπανγειλάμενοι</span> os candidatos a cargos municipais que fazem toda espécie de promessas; Larfeld I 494). — Da fé, <span class=\"greek\">πάντα</span> <span class=\"greek\">ἐπαγγέλλεται</span>, Hm 9:10. — Passivo (Just., D. 106, 3, <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐπηγγελμένην</span> … <span class=\"greek\">γῆν</span>): <span class=\"greek\">τὸ</span> <span class=\"greek\">σπέρμα</span>, <span class=\"greek\">ᾧ</span> <span class=\"greek\">ἐπήγγελται</span>, «a descendência à qual se destinava a promessa», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 3:19</a>; <span class=\"greek\">ἐπηγγελμέναι</span> <span class=\"greek\">δωρεαί</span>, «dádivas prometidas», 1Cl 35:4.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">②</span> Alegar ser muito competente em alguma coisa: «professar, pretender, apresentar-se como perito em algo», com acusativo (X., Mem. 1, 2, 7, <span class=\"greek\">τ</span>. <span class=\"greek\">ἀρετήν</span>; Hell. 3, 4, 3, <span class=\"greek\">στρατιάν</span>; Diog. L., prooem. 12, <span class=\"greek\">σοφίαν</span>; Lucian, Vit. Auct. 7, <span class=\"greek\">τ</span>. <span class=\"greek\">ἄσκησιν</span>; Philo, Virt. 54, <span class=\"greek\">θεοῦ</span> <span class=\"greek\">θεραπείαν</span>; Tat. 23, 2; 36, 1; 42, 1). <span class=\"greek\">θεοσέβειαν</span>, «devoção a Deus», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 2:10</a>; <span class=\"greek\">γνῶσιν</span>, «conhecimento», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.21\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 6:21</a>; <span class=\"greek\">πίστιν</span>, «fé», IEph 14:2; aqui também seguido de infinitivo (cf. Wsd 2:13, <span class=\"greek\">γνῶσιν</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">θεοῦ</span>), <span class=\"greek\">Χριστοῦ</span> <span class=\"greek\">εἶναι</span>, «ser de Cristo». — M-M. TW.</p></section></article>\n<article id=\"entry-epangelma-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπάγγελμα, ατος, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epángelma⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐπάγγελμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (ver verbete anterior; Pla., Demosth. e outros; Philo; Jos., C. Ap. 1, 24). Na literatura aqui considerada, somente a respeito de Deus:</p>\n<p class=\"entry-text\"><span class=\"sense-number\">①</span> Declaração de que se fará alguma coisa, com a implicação da obrigação de cumprir o que se afirma: «promessa». <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐ</span>., «segundo a promessa», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 3:13</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">②</span> O conteúdo daquilo que é prometido: «a coisa prometida» (Ael. Aristid. 52, p. 599 D.; Philo, Mut. Nom. 128). <span class=\"greek\">τὰ</span> <span class=\"greek\">μέγιστα</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">δεδώρηται</span>, «[Deus] prometeu coisas grandíssimas e no-las concedeu», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 1:4</a>. — TW.</p></section></article>\n<article id=\"entry-epago-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπάγω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epágō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐπάγω</span> (ver <span class=\"greek\">ἄγω</span>); futuro <span class=\"greek\">ἐπάξω</span>; primeiro aoristo, particípio <span class=\"greek\">ἐπάξας</span> (B-D-F §75; W-S. §13, 10; Mlt-H. 226; Rob. 348); segundo aoristo <span class=\"greek\">ἐπήγαγον</span>. Passivo: aoristo do subjuntivo, terceira pessoa do singular <span class=\"greek\">ἐπάχθῃ</span>, Sir 2:4; imperativo <span class=\"greek\">ἐπάχθητι</span> (Mel., Fgm. 8b 14); particípio <span class=\"greek\">ἐπαχθείς</span>, 4Macc 4:13 (códice A por <span class=\"greek\">ὑπ</span>-); particípio perfeito <span class=\"greek\">ἐπηγμένην</span>, 2Macc 7:38 (Hom. e posteriores; também Just., A I, 3, 1; D. 39, 2 e outros; 129, 4, <span class=\"greek\">ἐπήγαγον</span> acerca de palavras, «acrescentei»). «Fazer surgir ou ocorrer determinado estado ou condição, ocasionar, trazer alguma coisa sobre alguém», geralmente algo ruim; <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span> (Hes., Op. 240, <span class=\"greek\">πῆμά</span> <span class=\"greek\">τινι</span> <span class=\"greek\">ἐ</span>. e outros; OGI 669, 43, <span class=\"greek\">πολλοῖς</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">κινδύνους</span>; PRyl 144, 21 [38 d.C.], … <span class=\"greek\">μοι</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">αἰτίας</span>; Bar 4:9, 10, 14, 29; Dn 3:28, 31; TestJud 22:1; Philo, Mos. 1, 96; Jos., Vi. 18; SibOr 7, 154; Just., D. 39, 2, <span class=\"greek\">τὴν</span> <span class=\"greek\">κρίσιν</span>; 55, 2, <span class=\"greek\">κατάραν</span> e outros). <span class=\"greek\">κατακλυσμὸν</span> <span class=\"greek\">κόσμῳ</span> <span class=\"greek\">ἐπάξας</span>, «tendo trazido o dilúvio sobre o mundo», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 2:5</a> (cf. Gn 6:17; 3Macc 2:4 acerca do dilúvio, <span class=\"greek\">ἐπαγαγὼν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ἀμέτρητον</span> <span class=\"greek\">ὗδωρ</span>). <span class=\"greek\">λύπην</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πνεύματι</span>, «causar tristeza ao espírito», Hm 3:4. <span class=\"greek\">ἑαυτοῖς</span> <span class=\"greek\">ταχινὴν</span> <span class=\"greek\">ἀπώλειαν</span>, «trazer sobre si mesmos rápida destruição», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 2:1</a> (cf. <span class=\"greek\">ἑαυτοῖς</span> <span class=\"greek\">δουλείαν</span>, Demosth. 19, 259). Também <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινά</span> <span class=\"greek\">τι</span> (Êx 11:1; 33:5; Jr 6:19; Ez 28:7 e outros; TestJud 23:3; ApcEsdr 2:20, p. 26, 12 Tdf.): <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">αἷμα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀνθρώπου</span> <span class=\"greek\">τούτου</span>, «trazer sobre nós o sangue deste homem», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.28\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:28</a> (cf. Jz 9:24 B, <span class=\"greek\">ἐπαγαγεῖν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">αἵματα</span> <span class=\"greek\">αὐτῶν</span>, <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεῖναι</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">Ἀβιμελεχ</span>, <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">ἀπέκτεινεν</span> <span class=\"greek\">αὐτούς</span>). <span class=\"greek\">ἐ</span>. <span class=\"greek\">τισὶ</span> <span class=\"greek\">διωγμὸν</span> <span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span>, «suscitar, no interior de um grupo, perseguição contra alguém», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 14:2</a> D. — M-M.</p></section></article>\n<article id=\"entry-epagonizomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαγωνίζομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epagōnízomai⟧</span><span class=\"separator\">·</span><span>verbo médio depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐπαγωνίζομαι</span> (Dionys. Hal., Plut. e outros; inscrições; Philo): «empregar grande esforço em defesa de alguma coisa, lutar, contender». Quando usado em imagem atlética, o dativo que dele depende geralmente indica a pessoa contra quem se disputa (Plut., Fab. 187 [23, 2]) ou a pessoa ou coisa de que alguém depende como apoio na rivalidade (Plut., Numa 65 [8, 16], <span class=\"greek\">ἑτέροις</span> <span class=\"greek\">τεκμηρίοις</span>, em disputa por superioridade literária). <span class=\"greek\">τῇ</span> <span class=\"greek\">πίστει</span>, Jd 3, pelo contexto, só pode significar «pela fé» (cf. Plut., Mor. 1075d; Michel 394, 19 [séc. I a.C.], <span class=\"greek\">ἐπηγωνίσατο</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πόλιν</span> <span class=\"greek\">εὐνοίᾳ</span>). O componente semântico primordial no emprego do verbo em Jd 3 é o esforço realizado pelo sujeito em favor de uma causa nobre; assim, ele corresponde ao <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">σπουδὴν</span> <span class=\"greek\">ποιούμενος</span> do autor e manifesta <span class=\"greek\">ἀρετή</span>, expressando o ideal greco-romano de dedicação ao bem-estar da comunidade mais ampla. — DELG, s.v. <span class=\"greek\">ἄγω</span>. M-M. TW.</p></section></article>\n<article id=\"entry-epathroizo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαθροίζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epathroízō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐπαθροίζω</span>: «reunir além do já existente ou adicionalmente, aumentar», passivo com sentido ativo (Plut., Anton. 936 [44, 1], <span class=\"greek\">ἅμα</span> <span class=\"greek\">δ</span>’ <span class=\"greek\">ἡμέρᾳ</span> <span class=\"greek\">πολὺ</span> <span class=\"greek\">πλείονας</span> <span class=\"greek\">ἐπηθροίζοντο</span> = «logo que amanheceu, reuniram-se em número muito maior para atacar»); <span class=\"greek\">τῶν</span> <span class=\"greek\">ὄχλων</span> <span class=\"greek\">ἐπαθροιζομένων</span>, «quando as multidões aumentavam em número», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:29</a>. — DELG, s.v. <span class=\"greek\">ἄθρόος</span>.</p></section></article>\n<article id=\"entry-epainetos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἐπαίνετος, ου, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦Epaínetos⟧</span><span class=\"separator\">·</span><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">Ἐπαίνετος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span>: «Epêneto», um dos primeiros cristãos na Ásia, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 16:5</a>. Quanto ao nome, ver Diod S 19, 79, 2; SIG 43, 39; 585, 250; 944, 26; 1174, 4. — LGPN I. M-M.</p></section></article>"};
